import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring } from '../remotionShim';
{/* Start Google Fonts Loader */}
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]); 

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700;800;900`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */}



export type TinderUIProps = Record<string, any>;

const TinderUI: React.FC<TinderUIProps> = ({
  backgroundColor = "#F3F4F6",
  transparentBackground = false,
  durationInSeconds = 8,
  cards = [
    {
      name: "Jane",
      age: 24,
      distance: "2 miles away",
      imageUrl: "https://images.unsplash.com/photo-1517841905240-472988babdf9?auto=format&fit=crop&w=800&q=80"
    },
    {
      name: "Mark",
      age: 27,
      distance: "5 miles away",
      imageUrl: "https://images.unsplash.com/photo-1506794778202-cad84cf45f1d?auto=format&fit=crop&w=800&q=80"
    },
    {
      name: "Alex",
      age: 25,
      distance: "1 mile away",
      imageUrl: "https://images.unsplash.com/photo-1524504388940-b1c1722653e1?auto=format&fit=crop&w=800&q=80"
    }
  ],
  userImage = "https://images.unsplash.com/photo-1534528741775-53994a69daeb?auto=format&fit=crop&w=800&q=80"
}) => {
  useFontLoader(["Inter"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Constants for layout
  const cardWidth = width * 0.85;
  const cardHeight = height * 0.65;
  const centerX = (width - cardWidth) / 2;
  const centerY = (height - cardHeight) / 2;

  // State calculations for cards based on exact frame timings
  const getCardState = (index: number, f: number) => {
    if (index === 0) {
      return {
        x: interpolate(f, [35, 65], [0, 1500], { extrapolateRight: "clamp", extrapolateLeft: "clamp" }),
        y: interpolate(f, [35, 65], [0, 200], { extrapolateRight: "clamp", extrapolateLeft: "clamp" }),
        rotate: interpolate(f, [35, 65], [0, 30], { extrapolateRight: "clamp", extrapolateLeft: "clamp" }),
        scale: 1,
        likeOpacity: interpolate(f, [35, 45], [0, 1], { extrapolateRight: "clamp", extrapolateLeft: "clamp" }),
        nopeOpacity: 0
      };
    }
    if (index === 1) {
      return {
        x: interpolate(f, [90, 120], [0, -1500], { extrapolateRight: "clamp", extrapolateLeft: "clamp" }),
        y: interpolate(f, [55, 65, 90, 120], [40, 0, 0, 200], { extrapolateRight: "clamp", extrapolateLeft: "clamp" }),
        rotate: interpolate(f, [90, 120], [0, -30], { extrapolateRight: "clamp", extrapolateLeft: "clamp" }),
        scale: interpolate(f, [55, 65], [0.95, 1], { extrapolateRight: "clamp", extrapolateLeft: "clamp" }),
        likeOpacity: 0,
        nopeOpacity: interpolate(f, [90, 100], [0, 1], { extrapolateRight: "clamp", extrapolateLeft: "clamp" })
      };
    }
    if (index === 2) {
      return {
        x: interpolate(f, [145, 175], [0, 1500], { extrapolateRight: "clamp", extrapolateLeft: "clamp" }),
        y: interpolate(f, [55, 65, 110, 120, 145, 175], [80, 40, 40, 0, 0, 200], { extrapolateRight: "clamp", extrapolateLeft: "clamp" }),
        rotate: interpolate(f, [145, 175], [0, 30], { extrapolateRight: "clamp", extrapolateLeft: "clamp" }),
        scale: interpolate(f, [55, 65, 110, 120], [0.90, 0.95, 0.95, 1], { extrapolateRight: "clamp", extrapolateLeft: "clamp" }),
        likeOpacity: interpolate(f, [145, 155], [0, 1], { extrapolateRight: "clamp", extrapolateLeft: "clamp" }),
        nopeOpacity: 0
      };
    }
    return { x: 0, y: 0, rotate: 0, scale: 1, likeOpacity: 0, nopeOpacity: 0 };
  };

  // Match Screen Animations
  const matchOpacity = interpolate(frame, [165, 175], [0, 0.9], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const textScale = spring({ frame: frame - 170, fps, config: { damping: 12, mass: 0.8 } });
  
  const avatarSpringLeft = spring({ frame: frame - 180, fps, config: { damping: 14 } });
  const avatarSpringRight = spring({ frame: frame - 180, fps, config: { damping: 14 } });
  
  const leftAvatarX = interpolate(avatarSpringLeft, [0, 1], [-width, -160]);
  const rightAvatarX = interpolate(avatarSpringRight, [0, 1], [width, 160]);

  const particles = Array.from({ length: 40 });

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: "Inter", overflow: "hidden" }}>
      
      {/* Cards Stack */}
      <div style={{ position: "absolute", top: 0, left: 0, width: "100%", height: "100%" }}>
        {[2, 1, 0].map((index) => {
          const cardData = cards[index];
          if (!cardData) return null;
          const state = getCardState(index, frame);
          
          return (
            <div
              key={index}
              style={{
                position: "absolute",
                width: cardWidth,
                height: cardHeight,
                left: centerX,
                top: centerY,
                transform: `translateX(${state.x}px) translateY(${state.y}px) rotate(${state.rotate}deg) scale(${state.scale})`,
                borderRadius: 40,
                overflow: "hidden",
                boxShadow: "0 20px 50px rgba(0,0,0,0.15)",
                backgroundColor: "#fff",
                transition: "none",
                willChange: "transform"
              }}
            >
              <img src={cardData.imageUrl} alt={cardData.name} style={{ width: "100%", height: "100%", objectFit: "cover" }} />
              
              {/* Image Gradient Overlay */}
              <div style={{ position: "absolute", bottom: 0, width: "100%", height: "50%", background: "linear-gradient(to top, rgba(0,0,0,0.9) 0%, rgba(0,0,0,0) 100%)" }} />
              
              {/* Text Info */}
              <div style={{ position: "absolute", bottom: 40, left: 40, color: "white" }}>
                <div style={{ fontSize: 60, fontWeight: 700, display: "flex", alignItems: "baseline", gap: 15 }}>
                  {cardData.name} <span style={{ fontWeight: 400, fontSize: 45 }}>{cardData.age}</span>
                </div>
                <div style={{ fontSize: 30, marginTop: 10, fontWeight: 600, opacity: 0.9 }}>
                  {cardData.distance}
                </div>
              </div>

              {/* LIKE Stamp */}
              <div style={{
                position: "absolute", top: 80, left: 60, opacity: state.likeOpacity,
                border: "10px solid #4CAF50", color: "#4CAF50", fontSize: 70, fontWeight: 900,
                padding: "10px 30px", borderRadius: 20, transform: "rotate(-15deg)", letterSpacing: 5,
                textTransform: "uppercase"
              }}>
                LIKE
              </div>

              {/* NOPE Stamp */}
              <div style={{
                position: "absolute", top: 80, right: 60, opacity: state.nopeOpacity,
                border: "10px solid #F44336", color: "#F44336", fontSize: 70, fontWeight: 900,
                padding: "10px 30px", borderRadius: 20, transform: "rotate(15deg)", letterSpacing: 5,
                textTransform: "uppercase"
              }}>
                NOPE
              </div>
            </div>
          );
        })}
      </div>

      {/* Match Screen Overlay */}
      <div style={{
        position: "absolute", top: 0, left: 0, width: "100%", height: "100%",
        backgroundColor: "rgba(0,0,0,0.9)",
        opacity: matchOpacity,
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        justifyContent: "center",
        zIndex: 100,
        pointerEvents: "none"
      }}>
        
        {/* Match Text */}
        <h1 style={{
          color: "#fff",
          fontSize: 100,
          fontWeight: 900,
          fontStyle: "italic",
          textAlign: "center",
          textShadow: "0 0 40px rgba(255, 105, 180, 0.8)",
          transform: `scale(${textScale})`,
          margin: 0,
          marginBottom: 100
        }}>
          IT'S A MATCH!
        </h1>

        {/* Avatars Container */}
        <div style={{ position: "relative", width: "100%", height: 320, display: "flex", justifyContent: "center", alignItems: "center" }}>
          
          {/* User Avatar */}
          <div style={{
            position: "absolute",
            width: 320, height: 320,
            borderRadius: "50%",
            border: "8px solid #fff",
            overflow: "hidden",
            transform: `translateX(${leftAvatarX}px)`,
            boxShadow: "0 20px 50px rgba(0,0,0,0.5)",
            zIndex: 101
          }}>
            <img src={userImage} alt="User" style={{ width: "100%", height: "100%", objectFit: "cover" }} />
          </div>

          {/* Match Avatar (Card 3) */}
          <div style={{
            position: "absolute",
            width: 320, height: 320,
            borderRadius: "50%",
            border: "8px solid #fff",
            overflow: "hidden",
            transform: `translateX(${rightAvatarX}px)`,
            boxShadow: "0 20px 50px rgba(0,0,0,0.5)",
            zIndex: 102
          }}>
            <img src={cards[2]?.imageUrl || ""} alt="Match" style={{ width: "100%", height: "100%", objectFit: "cover" }} />
          </div>
        </div>

        {/* Confetti Explosion */}
        <div style={{ position: "absolute", top: "50%", left: "50%", width: 0, height: 0, zIndex: 99 }}>
          {particles.map((_, i) => {
            const angle = (i / particles.length) * Math.PI * 2;
            const distSpring = spring({ frame: frame - 190, fps, config: { damping: 20 } });
            const dist = interpolate(distSpring, [0, 1], [0, 800 + (i % 5) * 150]);
            const confX = Math.cos(angle) * dist;
            const confY = Math.sin(angle) * dist + (frame - 190 > 0 ? (frame - 190) * 3 : 0);
            const confRot = (frame - 190) * ((i % 3) + 1) * 5;
            const colors = ['#4CAF50', '#F44336', '#FFEB3B', '#2196F3', '#E91E63'];
            const confOpacity = interpolate(frame, [210, 230], [1, 0], { extrapolateRight: "clamp" });

            if (frame < 190) return null;

            return (
              <div key={`confetti-${i}`} style={{
                position: "absolute",
                width: 30, height: 30,
                backgroundColor: colors[i % colors.length],
                transform: `translate(-50%, -50%) translateX(${confX}px) translateY(${confY}px) rotate(${confRot}deg)`,
                opacity: confOpacity,
                borderRadius: i % 2 === 0 ? "50%" : "4px"
              }} />
            );
          })}
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default TinderUI;